def kth_smallest_amount(coins: List[int], k: int) -> int:
    if 1 in coins:
        return k
    n = len(coins)

    def count_distinct(X: int) -> int:
        total = 0
        for mask in range(1, 1 << n):
            lcm = 1
            cnt = 0
            for i in range(n):
                if mask & (1 << i):
                    c = coins[i]
                    g = gcd(lcm, c)
                    lcm = lcm // g * c
                    cnt += 1
                    if lcm > X:
                        break
            if lcm > X:
                continue
            if cnt % 2 == 1:
                total += X // lcm
            else:
                total -= X // lcm
        return total

    low = 1
    high = k * min(coins)
    while count_distinct(high) < k:
        high *= 2

    while low < high:
        mid = (low + high) // 2
        if count_distinct(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low

