def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.
    """
    import math

    if n < 1:
        return 0

    def integer_root(n, k):
        if n == 0:
            return 0
        if n == 1:
            return 1
        x = int(n ** (1.0 / k))
        while (x + 1) ** k <= n:
            x += 1
        while x ** k > n:
            x -= 1
        return x

    def mobius(k):
        if k == 1:
            return 1
        temp = k
        p = 2
        cnt = 0
        while p * p <= temp:
            if temp % p == 0:
                temp //= p
                if temp % p == 0:
                    return 0
                cnt += 1
            p += 1
        if temp > 1:
            cnt += 1
        return -1 if cnt % 2 else 1

    max_k = int(math.floor(math.log2(n)))
    total = 1  # for the number 1
    for k in range(2, max_k + 1):
        mu = mobius(k)
        if mu == 0:
            continue
        root = integer_root(n, k)
        total += -mu * (root - 1)
    return total

