def min_spanning_tree_mod_k(n: int, m: int, k: int, edges: List[Tuple[int, int, int]]) -> int:
    min_cost = None

    for combo in itertools.combinations(edges, n - 1):
        parent = list(range(n + 1))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py
                return True
            return False

        for u, v, w in combo:
            union(u, v)

        roots = set(find(i) for i in range(1, n + 1))
        if len(roots) == 1:
            total = sum(w for _, _, w in combo)
            cost = total % k
            if min_cost is None or cost < min_cost:
                min_cost = cost

    return min_cost

