def card_game_winner(n: int, cards: List[Tuple[int, int]]) -> str:
    A = [c[0] for c in cards]
    B = [c[1] for c in cards]
    memo = {}
    def win(mask):
        if mask in memo:
            return memo[mask]
        bits = [i for i in range(n) if mask & (1 << i)]
        for i_idx in range(len(bits)):
            i = bits[i_idx]
            for j in bits[i_idx+1:]:
                if A[i] == A[j] or B[i] == B[j]:
                    new_mask = mask ^ (1 << i) ^ (1 << j)
                    if not win(new_mask):
                        memo[mask] = True
                        return True
        memo[mask] = False
        return False
    initial = (1 << n) - 1
    return "Takahashi" if win(initial) else "Aoki"

