def sum_of_subsequence_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute powers of 2 modulo MOD
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    # dp[s][c] = number of subsequences with sum s and exactly c elements
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for x in nums:
        if x > k:
            continue
        for s in range(k, x - 1, -1):
            for c in range(n - 1, -1, -1):
                if dp[s - x][c]:
                    dp[s][c + 1] = (dp[s][c + 1] + dp[s - x][c]) % MOD

    ans = 0
    for c in range(1, n + 1):
        if dp[k][c]:
            ans = (ans + dp[k][c] * pow2[n - c]) % MOD

    return ans

