def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    """Given a list of n positive integers and a power k, compute the sum of all 
    subarray sums raised to the power k, modulo 998244353.
    """
    # Compute prefix sums: P[0] = 0, P[i+1] = P[i] + a[i]
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + a[i]

    # R[i] = Sum_{l=0}^{current_r} P[l]^i, T[i] = accumulated term
    R = [0] * (k + 1)
    T = [0] * (k + 1)

    for r in range(n):
        # Add P[r]^i to R[i]
        for i in range(k + 1):
            if i == 0:
                R[i] = (R[i] + 1) % MOD
            else:
                R[i] = (R[i] + pow_mod(P[r], i, MOD)) % MOD

        # Update T[i]
        for i in range(k + 1):
            T[i] = (T[i] + pow_mod(P[r + 1], k - i, MOD) * R[i]) % MOD

    # Combine using binomial theorem: Sum_{i=0}^{k} C(k,i)*(-1)^i * T[i]
    result = 0
    for i in range(k + 1):
        sign = -1 if i % 2 == 1 else 1
        term = comb(k, i) * sign * T[i]
        result = (result + term) % MOD

    return result % MOD

