import math

def find_cube_difference_pair(n: int) -> Optional[Tuple[int, int]]:
    max_d = int(n ** (1/3)) + 2
    for d in range(1, max_d + 1):
        if n % d != 0:
            continue
        m = n // d
        Delta = 3 * (4 * m - d * d)
        if Delta < 0:
            continue
        s = math.isqrt(Delta)
        if s * s != Delta:
            continue
        num = s - 3 * d
        if num <= 0:
            continue
        if num % 6 != 0:
            continue
        y = num // 6
        if y <= 0:
            continue
        x = y + d
        if x**3 - y**3 == n:
            return (x, y)
    return None

def max_partitions_with_one_change(s: str, k: int) -> int:
    def count_partitions(t, k):
        n = len(t)
        i = 0
        cnt = 0
        while i < n:
            distinct = set()
            j = i
            while j < n:
                c = t[j]
                if c not in distinct and len(distinct) == k:
                    break
                distinct.add(c)
                j += 1
            cnt += 1
            i = j
        return cnt

    best = count_partitions(s, k)
    n = len(s)
    for p in range(n):
        original = s[p]
        for new_c in 'abcdefghijklmnopqrstuvwxyz':
            if new_c == original:
                continue
            t = s[:p] + new_c + s[p+1:]
            cnt = count_partitions(t, k)
            if cnt > best:
                best = cnt
    return best

from typing import List, Tuple

def card_game_winner(n: int, cards: List[Tuple[int, int]}) -> str:
    valid = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if cards[i][0] == cards[j][0] or cards[i][1] == cards[j][1]:
                valid[i][j] = valid[j][i] = True
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def solve(mask: int) -> bool:
        if mask == 0:
            return False
        bits = [i for i in range(n) if mask & (1<<i)]
        L = len(bits)
        for a in range(L):
            i = bits[a]
            for b in range(a+1, L):
                j = bits[b]
                if valid[i][j]:
                    new_mask = mask ^ (1<<i) ^ (1<<j)
                    if not solve(new_mask):
                        return True
        return False
    return "Takahashi" if solve((1<<n)-1) else "Aoki"

def max_eleven_twentytwo_subsequence(s: str, l: int, r: int) -> int:
    sub = s[l-1:r]
    slash_positions = [i for i, ch in enumerate(sub) if ch == '/']
    if not slash_positions:
        return 0
    max_a = 0
    for i in slash_positions:
        count_1_before = sub[:i].count('1')
        count_2_after = sub[i+1:].count('2')
        a = min(count_1_before, count_2_after)
        if a > max_a:
            max_a = a
    return 2 * max_a + 1

