def max_kagamimochi(n: int, sizes: List[int]) -> int:
    i = 0
    j = n // 2
    count = 0
    while i < n // 2 and j < n:
        if sizes[j] >= 2 * sizes[i]:
            count += 1
            i += 1
            j += 1
        else:
            j += 1
    return count

def min_swaps_to_group_ones(n: int, s: str) -> int:
    ones = [i for i, ch in enumerate(s) if ch == '1']
    k = len(ones)
    if k <= 1:
        return 0
    q = [ones[i] - i for i in range(k)]
    q.sort()
    median = q[k // 2]
    return sum(abs(q[i] - median) for i in range(k))
